"))
  const inputRefs = useRef<(HTMLInputElement | null)[]>([])

  const handleChange = (value: string, index: number) => {
    if (!/^[0-9]?$/.test(value)) return // faqat raqam
    const newOtp = [...otp]
    newOtp[index] = value
    setOtp(newOtp)

    // Agar qiymat yozilsa, keyingisiga fokus o‘tkazish
